update known_safe_harbors set evidence_summary = 'Doxycycline-inducible MitoTimer biosensor (mitochondrial turnover monitoring) integrated at AAVS1, in iPSCs from a patient with the MAPT c.2013T>G mutation (FTDP-17, parkinsonism) and from a healthy donor. Functional tool for studying mitochondrial biogenesis specifically in dopaminergic neurons derived via directed differentiation.', stability = 'Functional tool validated in directed dopaminergic differentiation' where source_pmid = '40149527' and evidence_summary = 'Biossensor MitoTimer (monitorização do turnover mitocondrial) indutível por doxiciclina integrado em AAVS1, em iPSCs de doente com mutação MAPT c.2013T>G (FTDP-17, parkinsonismo) e de dador saudável. Ferramenta funcional para estudar biogénese mitocondrial especificamente em neurónios dopaminérgicos derivados por diferenciação dirigida.';
