update known_safe_harbors set evidence_summary = 'Paper that "de-orphanizes" CLYBL function: it acts as citramalyl-CoA lyase, linking the immunomodulatory metabolite itaconate to the vitamin B12 pathway. Confirms that homozygous loss is TOLERATED in apparently healthy individuals, with reduced circulating B12 as the only consistently reported phenotype -- reinforces CLYBL''s safety profile as a safe harbor.', stability = 'Homozygous loss tolerated in healthy individuals (natural precedent)' where source_pmid = '29056341' and evidence_summary = 'Paper que "desorfaniza" a função do CLYBL: opera como citramalil-CoA liase, liga o metabolito imunomodulador itaconato à via da vitamina B12. Confirma que a perda homozigótica é TOLERADA em indivíduos aparentemente saudáveis, com níveis reduzidos de B12 circulante como o único fenótipo consistente relatado -- reforça o perfil de segurança do CLYBL como safe harbor.';
update public_safe_harbors_staging set evidence_summary = 'Paper that "de-orphanizes" CLYBL function: it acts as citramalyl-CoA lyase, linking the immunomodulatory metabolite itaconate to the vitamin B12 pathway. Confirms that homozygous loss is TOLERATED in apparently healthy individuals, with reduced circulating B12 as the only consistently reported phenotype -- reinforces CLYBL''s safety profile as a safe harbor.', stability = 'Homozygous loss tolerated in healthy individuals (natural precedent)' where source_pmid = '29056341' and evidence_summary = 'Paper que "desorfaniza" a função do CLYBL: opera como citramalil-CoA liase, liga o metabolito imunomodulador itaconato à via da vitamina B12. Confirma que a perda homozigótica é TOLERADA em indivíduos aparentemente saudáveis, com níveis reduzidos de B12 circulante como o único fenótipo consistente relatado -- reforça o perfil de segurança do CLYBL como safe harbor.';

update known_safe_harbors set evidence_summary = 'Direct CLYBL vs. AAVS1 comparison (founding paper for CLYBL as a safe harbor, TALEN, 38-58% efficiency): CLYBL gave STRONGER transgene expression and LESS disruption of local genes than PPP1R12C/AAVS1 in the same study, in human iPSCs and NSCs. Simultaneous dual knock-in at AAVS1 + CLYBL successfully demonstrated.', stability = 'Stronger, less disruptive expression than AAVS1 in the same study' where source_pmid = '25587899' and evidence_summary = 'Comparação direta CLYBL vs. AAVS1 (paper fundador do uso de CLYBL como safe harbor, TALEN, 38-58% de eficiência): CLYBL deu expressão de transgene MAIS FORTE e MENOS perturbação de genes locais do que PPP1R12C/AAVS1 no mesmo estudo, em iPSCs e NSCs humanas. Knock-in duplo simultâneo em AAVS1 + CLYBL demonstrado com sucesso.';
update public_safe_harbors_staging set evidence_summary = 'Direct CLYBL vs. AAVS1 comparison (founding paper for CLYBL as a safe harbor, TALEN, 38-58% efficiency): CLYBL gave STRONGER transgene expression and LESS disruption of local genes than PPP1R12C/AAVS1 in the same study, in human iPSCs and NSCs. Simultaneous dual knock-in at AAVS1 + CLYBL successfully demonstrated.', stability = 'Stronger, less disruptive expression than AAVS1 in the same study' where source_pmid = '25587899' and evidence_summary = 'Comparação direta CLYBL vs. AAVS1 (paper fundador do uso de CLYBL como safe harbor, TALEN, 38-58% de eficiência): CLYBL deu expressão de transgene MAIS FORTE e MENOS perturbação de genes locais do que PPP1R12C/AAVS1 no mesmo estudo, em iPSCs e NSCs humanas. Knock-in duplo simultâneo em AAVS1 + CLYBL demonstrado com sucesso.';

