update known_safe_harbors set evidence_summary = 'High-efficiency TALEN and ZFN targeting two safe-harbor sites on chromosomes 13 and 19 (coordinates match CLYBL/13q32 and AAVS1/19q13) in a well-characterized iPSC line -- pluripotency characteristics maintained. Cre-recombinase-mediated cassette exchange strategy to rapidly generate new reporter lines on the same isogenic background, including targeting at progenitor-cell stages.', stability = 'Pluripotency maintained; supports rapid reporter-line generation' where source_pmid = '25777362' and evidence_summary = 'TALEN e ZFN de alta eficiência a alvejar dois sítios safe harbor nos cromossomas 13 e 19 (coordenadas batem com CLYBL/13q32 e AAVS1/19q13) em linha iPSC bem caracterizada -- características pluripotentes mantidas. Estratégia de troca de cassete mediada por Cre-recombinase para gerar rapidamente novas linhas repórter na mesma base isogénica, incluindo alvejamento em estádios de células progenitoras.';
update public_safe_harbors_staging set evidence_summary = 'High-efficiency TALEN and ZFN targeting two safe-harbor sites on chromosomes 13 and 19 (coordinates match CLYBL/13q32 and AAVS1/19q13) in a well-characterized iPSC line -- pluripotency characteristics maintained. Cre-recombinase-mediated cassette exchange strategy to rapidly generate new reporter lines on the same isogenic background, including targeting at progenitor-cell stages.', stability = 'Pluripotency maintained; supports rapid reporter-line generation' where source_pmid = '25777362' and evidence_summary = 'TALEN e ZFN de alta eficiência a alvejar dois sítios safe harbor nos cromossomas 13 e 19 (coordenadas batem com CLYBL/13q32 e AAVS1/19q13) em linha iPSC bem caracterizada -- características pluripotentes mantidas. Estratégia de troca de cassete mediada por Cre-recombinase para gerar rapidamente novas linhas repórter na mesma base isogénica, incluindo alvejamento em estádios de células progenitoras.';

update known_safe_harbors set evidence_summary = 'Founding paper (1992): AAV integration occurs via non-homologous recombination, with direct repeats found at a frequency far above chance, distributed across the AAVS1 sequence. Presence of a CpG island with transcription-factor binding elements suggestive of a TATA-less promoter. Direct evidence of endogenous transcriptional activity in the region (RNA amplified by RT-PCR) -- helps explain why AAVS1 is permissive for transgene expression.', stability = 'Structural/mechanistic finding explaining permissiveness (not a duration measurement)' where source_pmid = '1334463' and evidence_summary = 'Paper fundador (1992): integração do AAV ocorre via recombinação não-homóloga, com repetições diretas encontradas a uma frequência muito acima do acaso distribuídas pela sequência AAVS1. Presença de ilha CpG com elementos de ligação a fatores de transcrição sugestiva de promotor sem TATA-box. Evidência direta de atividade transcricional endógena na região (RNA amplificado por PCR após transcrição reversa) -- ajuda a explicar porque AAVS1 é permissivo à expressão de transgenes.';
