update known_safe_harbors set evidence_summary = 'Anti-GD2 CAR integrated at AAVS1 in hPSCs, differentiated into CAR macrophages (via endothelial-to-hematopoietic transition) -- a new immune cell type tested (macrophages, complementing T/NK/neutrophils already on record). Potent cytotoxic activity against GD2+ neuroblastoma and melanoma in vitro, and against neuroblastoma in vivo.', stability = 'Cytotoxic activity confirmed in vivo (duration not further quantified)' where source_pmid = '36638788' and evidence_summary = 'CAR anti-GD2 integrado em AAVS1 em hPSCs, diferenciadas em macrófagos CAR (via transição endotelial-hematopoiética) -- novo tipo de célula imune testada (macrófagos, complementa células T/NK/neutrófilos já registados). Atividade citotóxica potente contra neuroblastoma e melanoma GD2+ in vitro, e contra neuroblastoma in vivo.';
update public_safe_harbors_staging set evidence_summary = 'Anti-GD2 CAR integrated at AAVS1 in hPSCs, differentiated into CAR macrophages (via endothelial-to-hematopoietic transition) -- a new immune cell type tested (macrophages, complementing T/NK/neutrophils already on record). Potent cytotoxic activity against GD2+ neuroblastoma and melanoma in vitro, and against neuroblastoma in vivo.', stability = 'Cytotoxic activity confirmed in vivo (duration not further quantified)' where source_pmid = '36638788' and evidence_summary = 'CAR anti-GD2 integrado em AAVS1 em hPSCs, diferenciadas em macrófagos CAR (via transição endotelial-hematopoiética) -- novo tipo de célula imune testada (macrófagos, complementa células T/NK/neutrófilos já registados). Atividade citotóxica potente contra neuroblastoma e melanoma GD2+ in vitro, e contra neuroblastoma in vivo.';

update known_safe_harbors set locus_name = 'CCR5-delta32 allele (natural human variant, not a gene-editing target)', evidence_summary = 'Founding paper (1996) discovering the CCR5-delta32 allele: individuals homozygous for the 32-base-pair deletion (truncated, cell-surface-undetectable protein) are resistant to primary HIV-1 entry. Crucial safety fact: "this defect has no obvious phenotype in affected individuals" -- they are healthy. Heterozygous carriers reach ~20% in some populations. The strongest natural human proof that losing CCR5 is well tolerated.', stability = 'Natural human precedent: well tolerated in homozygous carriers (no obvious phenotype)' where source_pmid = '8756719' and evidence_summary = 'Paper fundador (1996) da descoberta do alelo CCR5-delta32: indivíduos homozigóticos para a deleção de 32 pares de bases (proteína truncada, não detetável à superfície celular) são resistentes à entrada do HIV-1 primário. Facto crucial de segurança: "este defeito não tem fenótipo óbvio nos indivíduos afetados" -- são saudáveis. Portadores heterozigóticos chegam a ~20% em algumas populações. É a prova humana natural mais forte de que perder CCR5 é bem tolerado.';
update public_safe_harbors_staging set locus_name = 'CCR5-delta32 allele (natural human variant, not a gene-editing target)', evidence_summary = 'Founding paper (1996) discovering the CCR5-delta32 allele: individuals homozygous for the 32-base-pair deletion (truncated, cell-surface-undetectable protein) are resistant to primary HIV-1 entry. Crucial safety fact: "this defect has no obvious phenotype in affected individuals" -- they are healthy. Heterozygous carriers reach ~20% in some populations. The strongest natural human proof that losing CCR5 is well tolerated.', stability = 'Natural human precedent: well tolerated in homozygous carriers (no obvious phenotype)' where source_pmid = '8756719' and evidence_summary = 'Paper fundador (1996) da descoberta do alelo CCR5-delta32: indivíduos homozigóticos para a deleção de 32 pares de bases (proteína truncada, não detetável à superfície celular) são resistentes à entrada do HIV-1 primário. Facto crucial de segurança: "este defeito não tem fenótipo óbvio nos indivíduos afetados" -- são saudáveis. Portadores heterozigóticos chegam a ~20% em algumas populações. É a prova humana natural mais forte de que perder CCR5 é bem tolerado.';

-- ===== batch 22 =====
update known_safe_harbors set evidence_summary = 'Important CORRECTION/NUANCE to the prior record on CCR5-delta32 "no phenotype": while it protects against HIV, CCR5-delta32 homozygosity is associated with a significantly INCREASED risk of symptomatic/fatal West Nile virus infection (odds ratio 4.4 in one cohort, 9.1 in another, both significant). Losing CCR5 is not "cost-free" -- it trades HIV resistance for greater vulnerability to a different specific viral infection. Important to qualify any therapeutic CCR5-targeting with this trade-off.', stability = 'Trade-off: HIV resistance vs. increased West Nile virus risk' where source_pmid = '16418398' and evidence_summary = 'CORREÇÃO/NUANCE importante ao registo anterior sobre CCR5-delta32 "sem fenótipo": embora proteja de HIV, homozigotia para CCR5-delta32 associa-se a risco AUMENTADO e estatisticamente significativo de infeção sintomática/fatal pelo vírus do Nilo Ocidental (odds ratio 4.4 numa coorte, 9.1 noutra, ambos significativos). Perder CCR5 não é "sem custo nenhum" -- troca resistência a HIV por maior vulnerabilidade a outra infeção viral específica. Importante qualificar qualquer uso terapêutico de CCR5 como alvo com este trade-off.';
update public_safe_harbors_staging set evidence_summary = 'Important CORRECTION/NUANCE to the prior record on CCR5-delta32 "no phenotype": while it protects against HIV, CCR5-delta32 homozygosity is associated with a significantly INCREASED risk of symptomatic/fatal West Nile virus infection (odds ratio 4.4 in one cohort, 9.1 in another, both significant). Losing CCR5 is not "cost-free" -- it trades HIV resistance for greater vulnerability to a different specific viral infection. Important to qualify any therapeutic CCR5-targeting with this trade-off.', stability = 'Trade-off: HIV resistance vs. increased West Nile virus risk' where source_pmid = '16418398' and evidence_summary = 'CORREÇÃO/NUANCE importante ao registo anterior sobre CCR5-delta32 "sem fenótipo": embora proteja de HIV, homozigotia para CCR5-delta32 associa-se a risco AUMENTADO e estatisticamente significativo de infeção sintomática/fatal pelo vírus do Nilo Ocidental (odds ratio 4.4 numa coorte, 9.1 noutra, ambos significativos). Perder CCR5 não é "sem custo nenhum" -- troca resistência a HIV por maior vulnerabilidade a outra infeção viral específica. Importante qualificar qualquer uso terapêutico de CCR5 como alvo com este trade-off.';

update known_safe_harbors set evidence_summary = 'Large-scale production protocol: doxycycline-inducible NGN2 cassette at AAVS1, neuron production at a scale of billions of cells within 5 days, cryopreservable or maintained for months -- confirms industrial/production-scale viability, not just bench-scale proof of concept.', stability = 'Cryopreservable, maintained for months at production scale' where source_pmid = '40022736' and evidence_summary = 'Protocolo de produção em larga escala: cassete NGN2 indutível por doxiciclina em AAVS1, produção de neurónios à escala de milhares de milhões de células em 5 dias, criopreserváveis ou mantidos por meses -- confirma viabilidade de produção industrial/escala, não só prova de conceito em bancada.';
