-- ===== batch 23 =====
update known_safe_harbors set locus_name = 'A2UCOE element (limitation correction)', evidence_summary = 'Important correction to the prior A2UCOE record: a new limitation discovered -- in inducible systems, A2UCOE causes gene-expression "leakage" even without the inducer (doxycycline), regardless of the fragment length tested (547-1337bp). Solution found: inserting an SV40 poly-A terminator as a spacer between A2UCOE and the inducible promoter completely eliminates the leakage AND strengthens the anti-silencing effect by >60%, stable for at least 30 days.', stability = 'Stable for at least 30 days with the terminator-spacer fix' where source_pmid = '40205378' and evidence_summary = 'Correção importante ao registo anterior sobre A2UCOE: descoberta uma limitação nova -- em sistemas indutíveis, A2UCOE causa "fuga" de expressão do gene mesmo sem o indutor (doxiciclina), independentemente do comprimento do fragmento testado (547-1337bp). Solução encontrada: inserir um terminador poly-A de SV40 como espaçador entre A2UCOE e o promotor indutível elimina completamente a fuga E reforça o efeito anti-silenciamento em >60%, estável por pelo menos 30 dias.';
update public_safe_harbors_staging set locus_name = 'A2UCOE element (limitation correction)', evidence_summary = 'Important correction to the prior A2UCOE record: a new limitation discovered -- in inducible systems, A2UCOE causes gene-expression "leakage" even without the inducer (doxycycline), regardless of the fragment length tested (547-1337bp). Solution found: inserting an SV40 poly-A terminator as a spacer between A2UCOE and the inducible promoter completely eliminates the leakage AND strengthens the anti-silencing effect by >60%, stable for at least 30 days.', stability = 'Stable for at least 30 days with the terminator-spacer fix' where source_pmid = '40205378' and evidence_summary = 'Correção importante ao registo anterior sobre A2UCOE: descoberta uma limitação nova -- em sistemas indutíveis, A2UCOE causa "fuga" de expressão do gene mesmo sem o indutor (doxiciclina), independentemente do comprimento do fragmento testado (547-1337bp). Solução encontrada: inserir um terminador poly-A de SV40 como espaçador entre A2UCOE e o promotor indutível elimina completamente a fuga E reforça o efeito anti-silenciamento em >60%, estável por pelo menos 30 dias.';

update known_safe_harbors set evidence_summary = 'REAL CLINICAL TRIAL (NCT04213469), not pre-clinical: non-viral anti-CD19 CAR with PD1 integration inserted at AAVS1 via CRISPR-Cas9, in patients with relapsed/refractory aggressive B-cell non-Hodgkin lymphoma. 87.5% complete remission (7 of 8 patients), durable responses, NO severe adverse events, effective even with a low infusion dose and low percentage of CAR+ cells.', stability = 'Durable clinical responses in a real trial (NCT04213469)' where source_pmid = '36045296' and evidence_summary = 'ENSAIO CLÍNICO REAL (NCT04213469), não pré-clínico: CAR anti-CD19 não-viral com integração PD1 inserido em AAVS1 via CRISPR-Cas9, em doentes com linfoma B não-Hodgkin agressivo recidivante/refratário. 87.5% de remissão completa (7 de 8 doentes), respostas duradouras, SEM eventos adversos graves, eficaz mesmo com dose de infusão baixa e baixa percentagem de células CAR+.';
