update known_safe_harbors set evidence_summary = '"Universal" correction of Hemophilia A: FVIII gene inserted at the human H11 locus via CRISPR/Cas9 in patient iPSCs, correcting different disease-causing mutations with the SAME strategy (no need for a per-variant design). Correction frequencies of 64% and 66% in two distinct patient lines, with no detectable off-target mutations. Endothelial cells differentiated from these iPSCs secreted functional FVIII.', stability = 'Functional secretion confirmed after endothelial differentiation' where source_pmid = '31105049' and evidence_summary = 'Correção "universal" de Hemofilia A: gene FVIII inserido no locus H11 humano via CRISPR/Cas9 em iPSCs de doente, corrigindo diferentes mutações causadoras da doença com a MESMA estratégia (não é preciso um desenho por variante). Frequências de correção de 64% e 66% em duas linhas de doentes distintas, sem mutações off-target detetáveis. Células endoteliais diferenciadas destas iPSCs secretaram FVIII funcional.';
update public_safe_harbors_staging set evidence_summary = '"Universal" correction of Hemophilia A: FVIII gene inserted at the human H11 locus via CRISPR/Cas9 in patient iPSCs, correcting different disease-causing mutations with the SAME strategy (no need for a per-variant design). Correction frequencies of 64% and 66% in two distinct patient lines, with no detectable off-target mutations. Endothelial cells differentiated from these iPSCs secreted functional FVIII.', stability = 'Functional secretion confirmed after endothelial differentiation' where source_pmid = '31105049' and evidence_summary = 'Correção "universal" de Hemofilia A: gene FVIII inserido no locus H11 humano via CRISPR/Cas9 em iPSCs de doente, corrigindo diferentes mutações causadoras da doença com a MESMA estratégia (não é preciso um desenho por variante). Frequências de correção de 64% e 66% em duas linhas de doentes distintas, sem mutações off-target detetáveis. Células endoteliais diferenciadas destas iPSCs secretaram FVIII funcional.';

update known_safe_harbors set evidence_summary = 'iPSCs generated from 3 individuals with a natural homozygous CCR5-delta32 mutation: phenotypically normal, with preserved differentiation potential into all 3 germ layers -- further confirmation that natural CCR5 loss is well tolerated at the pluripotent stem cell level.', stability = 'Phenotypically normal, full differentiation potential preserved' where source_pmid = '31234109' and evidence_summary = 'iPSCs geradas a partir de 3 indivíduos com mutação CCR5-delta32 homozigótica natural: fenotipicamente normais, com potencial de diferenciação preservado nas 3 camadas germinativas -- mais uma confirmação de que a perda natural de CCR5 é bem tolerada ao nível de estaminais pluripotentes.';
