update known_safe_harbors set evidence_summary = 'The most famous case of all, real clinical context (not experimental): the "Berlin patient" (Hutter et al. 2009) received a bone marrow transplant from a donor homozygous for CCR5-delta32 to treat leukemia -- became HIV-negative and remained free of detectable virus even after stopping antiretrovirals. Direct clinical proof that disabling CCR5 can control/cure HIV infection in humans, not just in a model.', stability = 'Durable, curative outcome in a real human clinical case' where source_pmid = '27942440' and evidence_summary = 'O caso mais famoso de todos, contexto clínico real (não experimental): o "doente de Berlim" (Hütter et al. 2009) recebeu transplante de medula óssea de um dador homozigótico para CCR5-delta32 para tratar leucemia -- ficou HIV-negativo e manteve-se livre de deteção viral mesmo após parar antirretrovirais. Prova clínica direta de que desativar CCR5 pode controlar/curar infeção por HIV em humanos, não só em modelo.';
