update known_safe_harbors set locus_name = '(general technical warning, not a locus)', evidence_summary = 'Linear DNA vectors with modified/blocked ends (including the CELiD type used in several AAVS1 records already catalogued) still integrate randomly into the genome in a substantial fraction of transfected cells (10-20%), even with blocked ends -- blocking the ends is not sufficient to prevent unwanted integration. Relevant for re-assessing the "extra safety" attributed to CELiD vectors in some earlier records.', stability = 'Technical caveat -- random integration still occurs with these vectors (not a locus-specific finding)' where source_pmid = '37100816' and evidence_summary = 'Vetores de DNA linear com pontas modificadas/bloqueadas (incluindo o tipo CELiD usado em vários registos AAVS1 já catalogados) continuam a integrar-se aleatoriamente no genoma numa fração substancial das células transfetadas (10-20%), mesmo com pontas bloqueadas -- bloquear as pontas não é suficiente para prevenir integração indesejada. Relevante para reavaliar a "segurança extra" atribuída a vetores CELiD nalguns registos anteriores.';
