update known_safe_harbors set locus_name = '(general technical warning, not a locus)', evidence_summary = 'Safety finding relevant to any insertion at any safe harbor: repair of CRISPR-Cas9-induced double-strand breaks can cause large (multi-kb) deletions and complex genomic rearrangements directly at the target site itself -- not only at distant off-target sites. This was underestimated by earlier analyses focused only on the immediate vicinity of the cut. Relevant to any editing strategy at any of the loci already catalogued, regardless of how "safe" the locus is.', stability = 'Technical caveat -- large deletions/rearrangements possible at the target site itself (not a locus-specific finding)' where source_pmid = '30010673' and evidence_summary = 'Achado de segurança relevante para qualquer inserção em qualquer safe harbor: reparação de quebras de cadeia dupla induzidas por CRISPR-Cas9 pode causar deleções grandes (várias kb) e rearranjos genómicos complexos diretamente no próprio local-alvo -- não só em sítios off-target distantes. Isto foi subestimado por análises anteriores focadas só na vizinhança imediata do corte. Relevante para qualquer estratégia de edição em qualquer dos loci já catalogados, independentemente de quão "seguro" o locus seja.';
